/**
 * Country Names Tests
 *
 * The place page shows a place's country from its ISO 3166-1 alpha-3
 * code. Names come from `themes/base/data/countries.yaml`, generated by
 * `scripts/generate-country-names.js` from the CLDR data in Node, with a
 * site's `place.countries.<ALPHA3>` i18n key taking precedence.
 *
 * These tests check that the data file covers all 249 assigned codes in
 * English and Spanish, that a code outside the fourteen the bundles
 * name (Germany, DEU) has a name in both languages, that those fourteen
 * bundle names match the data file so the countries render the same
 * either way, and that the place template reads the data file and holds
 * no fixed list of codes.
 *
 * @version v1.6.0
 */

import { describe, it, expect } from 'vitest';
import fs from 'fs';
import path from 'path';
import { createRequire } from 'module';
import { parse } from 'smol-toml';

const require = createRequire(import.meta.url);
const yaml = require('js-yaml');
const { ALPHA3_TO_ALPHA2 } = require('../scripts/generate-country-names.js');

const BASE = path.join(__dirname, '..', 'themes', 'base');
const countries = yaml.load(fs.readFileSync(path.join(BASE, 'data', 'countries.yaml'), 'utf8'));

describe('countries.yaml', () => {
  it('keeps the alpha-2 code of Norway a string', () => {
    expect(countries.NOR.alpha2).toBe('NO');
  });

  it('lists every assigned ISO 3166-1 code with English and Spanish names', () => {
    expect(Object.keys(countries)).toHaveLength(249);
    expect(Object.keys(ALPHA3_TO_ALPHA2)).toHaveLength(249);
    for (const [alpha3, entry] of Object.entries(countries)) {
      expect(entry.alpha2, alpha3).toBe(ALPHA3_TO_ALPHA2[alpha3]);
      expect(typeof entry.en, alpha3).toBe('string');
      expect(typeof entry.es, alpha3).toBe('string');
    }
  });

  it('names a country outside the fourteen bundle keys in both languages', () => {
    expect(countries.DEU).toEqual({ alpha2: 'DE', en: 'Germany', es: 'Alemania' });
    expect(countries.PRY.es).toBe('Paraguay');
    expect(countries.CUB.en).toBe('Cuba');
  });

  it('agrees with the place.countries names in both bundles', () => {
    for (const lang of ['en', 'es']) {
      const bundle = parse(fs.readFileSync(path.join(BASE, 'i18n', `${lang}.toml`), 'utf8'));
      const names = bundle.place.countries;
      expect(Object.keys(names)).toHaveLength(14);
      for (const [alpha3, name] of Object.entries(names)) {
        expect(countries[alpha3][lang], `${lang} ${alpha3}`).toBe(name);
      }
    }
  });
});

describe('place template', () => {
  const src = fs.readFileSync(path.join(BASE, 'layouts', 'lugar', 'single.html'), 'utf8');

  it('reads the country name from the data file', () => {
    expect(src).toMatch(/hugo\.Data\.countries/);
  });

  it('checks the place.countries i18n key first', () => {
    expect(src).toMatch(/place\.countries\.%s/);
  });

  it('holds no fixed list of country codes', () => {
    expect(src).not.toMatch(/"COL" \(i18n/);
  });
});

// Version: v1.6.0
